import{_ as e,o as t,c as n,a2 as l}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"LLM 工程基础：训练、推理与模型适配","description":"","frontmatter":{"title":"LLM 工程基础：训练、推理与模型适配","date":"2026-08-29T00:00:00.000Z","isComment":true,"categories":["AI","LLM"],"tags":["LLM","Training","Inference"]},"headers":[],"relativePath":"28-llm-engineering-foundations.md","filePath":"28-llm-engineering-foundations.md","lastUpdated":1790425174000}'),i={name:"28-llm-engineering-foundations.md"};function r(s,a,o,d,h,p){return t(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="llm-工程基础-训练、推理与模型适配" tabindex="-1">LLM 工程基础：训练、推理与模型适配 <a class="header-anchor" href="#llm-工程基础-训练、推理与模型适配" aria-label="Permalink to &quot;LLM 工程基础：训练、推理与模型适配&quot;">​</a></h1><blockquote><p>本篇补齐 Agent 开发之前容易被跳过的一层：模型从哪里来、为什么会产生这些能力，以及部署和适配时真正需要关心什么。</p><p><strong>边界：</strong> 这里只讲训练 / 推理 / 微调决策。Schema 与 Tool 设计见 <a href="./09-tools-system-design">09</a>，Parser API 见 <a href="./langchain/10-output-parsers">LC10</a>。</p><p><strong>配套实验：</strong> <a href="./examples#01-结构化输出">01 结构化输出</a> — 非法 JSON 拒绝并重试，不把脏数据交给业务。</p></blockquote><h2 id="学完要能回答什么" tabindex="-1">学完要能回答什么 <a class="header-anchor" href="#学完要能回答什么" aria-label="Permalink to &quot;学完要能回答什么&quot;">​</a></h2><ul><li>预训练、SFT、RLHF、DPO 分别解决什么问题？</li><li>为什么上下文变长会增加成本和延迟？</li><li>KV Cache、Batching、量化分别优化什么？</li><li>什么时候应该换模型、改 Prompt、做 RAG，什么时候才值得微调？</li></ul><h2 id="一条完整链路" tabindex="-1">一条完整链路 <a class="header-anchor" href="#一条完整链路" aria-label="Permalink to &quot;一条完整链路&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据清洗 → Tokenizer → 预训练 → SFT → 偏好对齐 → 推理服务 → 应用层</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>不要把“模型能力”和“应用效果”混为一谈。应用质量通常由模型、上下文、工具、数据和评测共同决定。</p><h2 id="tokenizer-与上下文" tabindex="-1">Tokenizer 与上下文 <a class="header-anchor" href="#tokenizer-与上下文" aria-label="Permalink to &quot;Tokenizer 与上下文&quot;">​</a></h2><p>模型看到的不是字符，而是 token。token 数量决定上下文占用、输入费用和部分延迟。</p><p>工程上至少要关注：</p><ul><li>中文、代码、URL、表格的切分效率不同。</li><li><code>max_tokens</code> 是输出上限，不等于完整上下文容量。</li><li>历史消息、工具 Schema、检索片段都会占用上下文。</li><li>截断应按消息重要性、文档相关性和任务状态处理，不能简单取最后 N 条。</li></ul><h2 id="训练阶段的分工" tabindex="-1">训练阶段的分工 <a class="header-anchor" href="#训练阶段的分工" aria-label="Permalink to &quot;训练阶段的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>常见数据</th><th>应用开发者的判断</th></tr></thead><tbody><tr><td>预训练</td><td>学习语言和世界知识</td><td>大规模文本</td><td>通常不自己做</td></tr><tr><td>SFT</td><td>学习任务格式和行为</td><td>指令-回答</td><td>需要稳定风格或格式时考虑</td></tr><tr><td>RLHF</td><td>对齐人类偏好</td><td>排序和反馈</td><td>了解原理即可</td></tr><tr><td>DPO</td><td>直接使用偏好对</td><td>chosen/rejected</td><td>小规模定制时更易落地</td></tr><tr><td>RAG</td><td>注入外部、可更新知识</td><td>文档和检索结果</td><td>优先于微调解决知识更新</td></tr></tbody></table><h2 id="推理优化" tabindex="-1">推理优化 <a class="header-anchor" href="#推理优化" aria-label="Permalink to &quot;推理优化&quot;">​</a></h2><ul><li><strong>KV Cache</strong>：复用已计算的注意力键值，降低生成后续 token 的重复计算。</li><li><strong>Batching</strong>：把多个请求合并执行，提高 GPU 利用率，但可能增加排队延迟。</li><li><strong>量化</strong>：用更低精度表示权重，降低显存和成本，需用 Eval 验证质量损失。</li><li><strong>Streaming</strong>：改善首 token 后的用户感知延迟，不等于总计算量减少。</li><li><strong>模型路由</strong>：简单任务用小模型，复杂任务升级，并用回归集约束质量。</li></ul><h2 id="lora、qlora-与微调决策" tabindex="-1">LoRA、QLoRA 与微调决策 <a class="header-anchor" href="#lora、qlora-与微调决策" aria-label="Permalink to &quot;LoRA、QLoRA 与微调决策&quot;">​</a></h2><p>微调适合改变稳定行为、格式、术语和风格；不适合替代实时知识库、权限系统或业务规则。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>知识经常变化       → RAG</span></span>
<span class="line"><span>行为/格式长期稳定   → SFT 或 LoRA</span></span>
<span class="line"><span>需要降低单次成本   → 小模型蒸馏或量化</span></span>
<span class="line"><span>只是某几个 case 错 → 先改数据、Prompt 和 Eval</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="实践任务" tabindex="-1">实践任务 <a class="header-anchor" href="#实践任务" aria-label="Permalink to &quot;实践任务&quot;">​</a></h2><ol><li>用同一组 20 条问题比较大模型、小模型和带 RAG 的效果。</li><li>记录输入 token、输出 token、首 token 延迟、总耗时和成本。</li><li>为一个结构化输出任务设计 SFT、RAG、Prompt 三种方案，并用同一 Eval 集比较。</li></ol><h2 id="与已有内容的关系" tabindex="-1">与已有内容的关系 <a class="header-anchor" href="#与已有内容的关系" aria-label="Permalink to &quot;与已有内容的关系&quot;">​</a></h2><ul><li>Transformer 原理见 <a href="./02-transformer-explained">02</a>。</li><li>模型选型见 <a href="./03-llm-comparison-guide">03</a>。</li><li>成本和路由见 <a href="./18-agent-production-checklist">18</a>。</li><li>评测方法见 <a href="./22-agent-eval-regression">22</a>。</li></ul>`,22)])])}const m=e(i,[["render",r]]);export{u as __pageData,m as default};
